memi = memi - mean(memi);
dt = 0.78125;
t = (0 : length(memi) - 1) * dt;
N = length(memi);

% fft
fft_result = fft(memi);
fft_result = fftshift(fft_result);
fft_amp = abs(fft_result) / N;
fft_phi = angle(fft_result);
fft_power = fft_amp.^2;

% frequency axis
df = 1 / dt;
f = (-length(fft_result)/2 : length(fft_result)/2 - 1) * (df / length(fft_result));

% spectrum 1
figure(1);
tiledlayout(3, 1);

nexttile;
plot(t, memi);
title('memi time series');
xlabel('time [sec]'); ylabel('sea level [m]');

nexttile;
plot(f, fft_amp);
title('memi amplitude spectrum');
xlabel('f [Hz]'); ylabel('amplitude [m]');
xlim([min(f), max(f)]);

nexttile;
plot(f, fft_phi);
title('memi phase spectrum');
xlabel('f [Hz]'); ylabel('phase [rad]');
xlim([min(f), max(f)]);

% spectrum 2
figure(2);
tiledlayout(2, 1);

nexttile;
plot(f(1151:end), 2*fft_amp(1151:end));
title('memi amplitude spectrum');
xlabel('f [Hz]'); ylabel('amplitude [m]');
xlim([min(f(1151:end)), max(f(1151:end))]);

nexttile;
plot(f(1151:end), fft_phi(1151:end));
title('memi phase spectrum');
xlabel('f [Hz]'); ylabel('phase [rad]');
xlim([min(f(1151:end)), max(f(1151:end))]);

% spectrum 3
figure(3);
tiledlayout(2, 1);

nexttile;
plot(f(1151:end), 2*fft_power(1151:end));
title('memi power spectrum');
xlabel('f'); ylabel('power specturm');
xlim([min(f(1151:end)), max(f(1151:end))]);

nexttile;
plot(f(1151:end), 2*fft_power(1151:end)*N/df);
title('memi power spectral density');
xlabel('f'); ylabel('power spectural density');
xlim([min(f(1151:end)), max(f(1151:end))]);

% parseval theorem
lhs = var(memi);
rhs = sum(fft_power);
abs_error = abs(lhs - rhs);

% histogram & reyleigh
h_real = 2 * abs(hilbert(memi));
h = linspace(0, 16, 100);
h_rms = sqrt(sum(h_real.^2 / N));
reyleigh = 2 .* h ./ h_rms.^2 .* exp(-(h./h_rms).^2);

figure(4);
hold on;
histogram(h_real, 12, 'Normalization', 'pdf');
plot(h, reyleigh, 'LineWidth', 3);
hold off;
title('wave height histogram with reyle');
xlabel('wave height'); ylabel('probability');

% histogram
figure(5);
histogram(2*abs(memi), 12, 'Normalization', 'pdf');
title('wave height histogram');
xlabel('wave height'); ylabel('probability');